\begin{tikzpicture}[font=\sffamily, scale=1.2]
    % Define center O at origin
    \coordinate (O) at (0,0);

    % Radius
    \def\R{3}

    % Angles for points on the circle
    % Let C be at -30 deg, B be at -110 deg to make a nice geometry for tangents and angles
    % Let's calculate precise positions to match the given angles approximately or standard layout.
    % Given: angle OAB = 62, angle ABC = 76, angle DAE = 70.
    % Let's place points visually clear for an O-Level geometry problem.

    \coordinate (C) at (-30:\R);
    \coordinate (B) at (-100:\R);
    \coordinate (A) at (-160:\R);
    \coordinate (E) at (100:\R);
    \coordinate (D) at (40:\R);

    % Draw circle
    \draw (O) circle (\R);

    % Draw polygon / chords
    \draw (A) -- (B) -- (C);
    \draw (A) -- (E);
    \draw (D) -- (A);
    \draw (D) -- (E);
    % BC intersects AE at G
    \coordinate (G) at (intersection of A--E and B--C);

    % Tangents at C and B
    % Tangent at C is perpendicular to OC
    % Tangent at B is perpendicular to OB
    % They intersect at I
    \pgfmathset5angle{atan2(y(C),x(C))}
    % Let's compute tangent line using slope perpendicular to radius
    % Radius OC is at angle -30. Tangent is at angle -30 + 90 = 60 and -30 - 90 = -120.
    % Radius OB is at angle -100. Tangent is at angle -100 + 90 = -10.
    % Let's find intersection I of tangents at B and C:
    % OC vector: (\R*cos(-30), \R*sin(-30))
    % OB vector: (\R*cos(-100), \R*sin(-100))
    % Tangent at C: line through C perpendicular to OC
    % Tangent at B: line through B perpendicular to OB

    % Let's use polar/geometric approximations that look correct or calculate exact intersection I:
    % Using tikz intersection:
    \coordinate (T1) at ($(C) + ({-\R*sin(-30)},{\R*cos(-30)})ോ); % direction vector
    \coordinate (T2) at ($(B) + ({-\R*sin(-100)},{\R*cos(-100)})ോ);

    % Actually, simpler to define tangents by angle from center O:
    % Tangents from external point I to circle with centre O at C and B.
    % Since OC = OB = R, IC = IB, triangle OBI congruent to OCI, OI bisects angle BIC and angle COB.
    % Let's just find I by extending perpendiculars:
    \path[name path=tanC] (C) -- ++({-sin(-30)}, {cos(-30)});
    \path[name path=tanB] (B) -- ++({-sin(-100)}, {cos(-100)});
    \coordinate (I) at (intersection of C--{$(C)+({-sin(-30)}, {cos(-30)})$}%
                     and B--{$(B)+({-sin(-100)}, {cos(-100)})$});

    % Draw tangents HI and BI (H is on the tangent line from C, wait: "The lines HI and BI are tangents to the circle at C and B respectively")
    % So H is a point on the tangent at C. Let's place H along the tangent line beyond C.
    \coordinate (H) at ($(C)!1.4!(I)$); % H is further along, or I is between H and C? 
    % "lines HI and BI" implies I is the intersection, H is on the tangent at C.
    \coordinate (H) at ($(C)!1.5!(I)$); % let's check order: H-C-I or H-I-C? Usually tangent from H touching at C means H-C-I or similar. Let's draw H--I--B where tangent touches at C and B.
    % If tangents are HI and BI, they meet at I, so the tangent lines are HI (touching at C) and BI (touching at B). This means C lies on segment HI!

    \draw (H) -- (I) -- (B);
    \draw (C) -- (O);
    \draw (B) -- (O);
    \draw (A) -- (O);
    \draw (C) -- (I); % just to be sure

    % Draw lines for chords
    \draw (C) -- (D); % for angle DCB
    \draw (D) -- (B);

    % Label points
    \node[above left] at (O) {$O$};
    \node[above] at (A) {$A$};
    \node[below left] at (B) {$B$};
    \node[right] at (C) {$C$};
    \node[above right] at (D) {$D$};
    \node[above] at (E) {$E$};
    \node[above right] at (I) {$I$};
    \node[above left] at (H) {$H$};
    \node[above] at (G) {$G$};

    % Draw dots at vertices
    foreach \p in {O,A,B,C,D,E,I,H,G} {
        \fill (\p) circle (1.5pt);
    }

    % Additional required connections to make the figure complete as per description
    \draw (D) -- (B);

\end{tikzpicture}

