\begin{tikzpicture}[font=\sffamily, scale=1.1]
    % Define center O at origin
    \coordinate (O) at (0,0);

    % Radius
    \def\R{3}

    % Coordinates of points on the circle
    \coordinate (C) at (-35:\R);
    \coordinate (B) at (-105:\R);
    \coordinate (A) at (-155:\R);
    \coordinate (E) at (110:\R);
    \coordinate (D) at (35:\R);

    % Draw circle
    \draw (O) circle (\R);

    % Draw polygon / chords
    \draw (A) -- (B) -- (C);
    \draw (A) -- (E);
    \draw (D) -- (A);
    \draw (D) -- (E);
    \draw (D) -- (C);
    \draw (D) -- (B);

    % Intersection G of BC and AE
    \coordinate (G) at (intersection of A--E and B--C);

    % Tangents at C and B meeting at I
    % Radius OC is at angle -35. Tangent line at C is perpendicular to OC.
    % Radius OB is at angle -105. Tangent line at B is perpendicular to OB.
    % We can find the intersection I of the two tangents geometrically using calc:
    % Tangent direction at C is rotated +90 from OC, so angle is -35+90 = 55.
    % Tangent direction at B is rotated +90 from OB, so angle is -105+90 = -15.
    \coordinate (I) at (intersection of C--++(55:4) and B--++(-15:4));

    % H is on the tangent line HI such that C lies between H and I (or similar, given "lines HI and BI")
    \coordinate (H) at ($(C)!2.2!(I)$);

    % Draw tangents
    \draw (H) -- (I);
    \draw (B) -- (I);

    % Radii to points of contact
    \draw (C) -- (O);
    \draw (B) -- (O);
    \draw (A) -- (O);

    % Label points
    \node[above left] at (O) {$O$};
    \node[left] at (A) {$A$};
    \node[below left] at (B) {$B$};
    \node[right] at (C) {$C$};
    \node[above right] at (D) {$D$};
    \node[above left] at (E) {$E$};
    \node[above right] at (I) {$I$};
    \node[above right] at (H) {$H$};
    \node[above right] at (G) {$G$};

    % Draw dots at vertices
    \foreach \p in {O,A,B,C,D,E,I,H,G} {
        \fill (\p) circle (1.5pt);
    }

\end{tikzpicture}

